void SVC_Handler_C(uint32_t *pStart_address){
	printf("Inside SVC_Handler \n");
	//When we call the handler_c, the start address will be pointing to R0
	//As the stack placement order, in 6 position we can get the return address
	uint32_t R0_reg =  pStart_address[0];

	uint32_t R1_reg =  pStart_address[1];

	//When we call the handler_c, the start address will be pointing to R0
	//As the stack placement order, in 6 position we can get the return address
	uint8_t *pReturn_address = (uint8_t*) pStart_address[6];

	//by decrementing the value by 2, we can reach the address of SVC number
	pReturn_address-=2;

	uint8_t svc_number = *pReturn_address;

	printf("svc_number %d \n", svc_number);

	int32_t final;
	switch(svc_number){
	case 36:
		final = R0_reg + R1_reg;
		break;
	case 37:
			final = R0_reg - R1_reg;
			break;
	case 38:
			final = R0_reg  * R1_reg;
			break;
	case 39:
			final = R0_reg / R1_reg;
			break;
	default:
		printf("enter proper svc number \n");
	}


	//Return the final result and capture it in caller function
	pStart_address[0] = final;
}
